export const target = {minecraft:'26.3',java:'25',loader:'0.19.5',api:'0.160.5+26.3',loom:'1.17.19',gradle:'9.6.0',checked:'2026-10-01'};
export const units = [
 ['Java, with purpose','Types, methods, control flow, and collections','Foundation','code'],
 ['Design with objects','Classes, contracts, composition, and state','Foundation','layers'],
 ['Your development environment','Java 25, Gradle, debugging, and the mod lifecycle','Foundation','terminal'],
 ['Content in the game','Registries, items, blocks, and resource packs','Fabric 26.3','box'],
 ['World interactions','Block states, logical sides, interactions, and events','Fabric 26.3','cursor'],
 ['Machines that remember','Block entities, ticking, saving, and inventories','Fabric 26.3','cog'],
 ['Automation systems','Recipes, transactions, transfers, and redstone','Engineering','workflow'],
 ['Multiplayer by design','Payloads, validation, synchronization, and menus','Engineering','network'],
 ['Make it visible','Models, rendering, interpolation, and input','Engineering','monitor'],
 ['Connected mechanics','Graphs, rotation, stress, and topology','Advanced','branch'],
 ['Worlds & reliability','26.3 worldgen, migrations, profiling, and testing','Advanced','globe'],
 ['Build something worth shipping','Architecture, integrations, packaging, and releases','Advanced','rocket'],
].map(([title,subtitle,level,icon],i)=>({id:i+1,title,subtitle,level,icon}));
const java='https://dev.java/learn/';
const fabric='https://docs.fabricmc.net/develop/';
const migration='https://fabricmc.net/2026/09/15/263.html';
function L(unit,slug,title,objective,prose,code,walkthrough,pitfall,question,options,answer,explanation,reference=fabric,language='java') {
 return {id:slug,unit,title,objective,paragraphs:prose.split('|'),code,walkthrough:walkthrough.split('|'),pitfall,quiz:{question,options,answer,explanation},reference,language,minutes:12};
}
export const lessons = [
L(1,'types','Types are contracts','Choose types deliberately and recognize integer division.',
'Python attaches types to values at runtime. Java also checks declared types before the program starts. A method accepting int cannot be called with a String simply because the text contains digits. This turns many mistakes into compiler errors before Minecraft ever launches.|For machine code, int is suitable for bounded item counts, long for larger accumulated totals, double for continuous ratios, and boolean for decisions. Integer division discards the fractional part. If both operands are int, assigning the result to double afterward does not restore that fraction. Make an operand floating-point before dividing.',
'static double fillRatio(int stored, int capacity) {\n    if (capacity <= 0) return 0.0;\n    return (double) stored / capacity;\n}',
'static means the calculation does not need an instance.|The return type promises a double result.|The cast happens before division; 3 / 4 would otherwise produce 0.',
'Changing only the receiving variable to double does not change the type of the calculation.',
'What does double ratio = 3 / 4; store?',['0.75','0.0','A compiler error','3.0'],1,'Both operands are integers. Java divides them as integers, producing 0, then widens that result to 0.0.',java),
L(1,'methods','Methods and return values','Separate a calculation from the code that uses it.',
'A Java method declares its return type, name, and parameter types. Parameters are local names for the arguments supplied by a caller. A method returning a value must produce a compatible result on every normal execution path; void means it returns no value.|Keep calculations independent of Minecraft where possible. A processing-cost function should accept the values it needs and return a result. It should not also search the world, remove items, and play a sound. Separating a decision from its effects makes the decision straightforward to test.',
'static int batchCost(int count, int costPerItem) {\n    return count * costPerItem;\n}\n\n// Inside another method:\nint required = batchCost(4, 12);',
'The declaration establishes two int inputs and one int output.|Calling the method supplies 4 and 12.|The result is 48; no world state changes.',
'A method signature is a contract. Renaming its parameters does not change the argument order.',
'Which design is easiest to test without launching Minecraft?',['A method that locates every chest in a world','A method that opens a screen','A method that calculates cost from numeric arguments','A method that reads the current player globally'],2,'An isolated calculation has explicit inputs and an observable return value. It needs no game runtime.',java),
L(1,'guards','Guard clauses and invariants','Reject invalid operations before changing state.',
'Machine logic usually has more failure paths than success paths: missing input, full output, insufficient power, or an unloaded neighbor. Guard clauses return early for each invalid case so that the successful path remains readable.|An invariant is a condition your system promises to preserve. For a storage cell, charge must stay between zero and capacity. Checking before mutation is stronger than trying to repair a negative value afterward. Also check invalid requests: a negative extraction amount could accidentally add charge.',
'static boolean canExtract(int charge, int requested) {\n    if (requested < 0) return false;\n    if (requested > charge) return false;\n    return true;\n}',
'The first guard rejects invalid input.|The second guard enforces available capacity.|Only the final path authorizes extraction; this method itself does not extract.',
'Do not spend resources and only then discover that the output cannot fit.',
'Why reject a negative extraction request?',['It might increase storage if subtracted','Java forbids negative integers','Every negative value crashes Minecraft','It makes the method static'],0,'Subtracting a negative amount increases the stored amount. Validating requests protects the invariant.',java),
L(1,'collections','Collections and iteration','Choose collections based on the operations you need.',
'List preserves an ordered sequence and allows duplicates. Set represents unique membership. Map associates keys with values. Their generic type parameters describe what they contain: Map<String, Integer> maps names to integer counts. Java collections use wrapper types such as Integer rather than primitive int in generic arguments.|For a connected machine search, a queue contains pending work and a set tracks visited positions. A list alone does not prevent you from revisiting the same block forever. Be careful when mutating a collection while iterating over it; collect changes separately or use a supported iterator operation.',
'Set<String> visited = new HashSet<>();\nQueue<String> pending = new ArrayDeque<>();\npending.add("motor");\nwhile (!pending.isEmpty()) {\n    String node = pending.remove();\n    if (!visited.add(node)) continue;\n    // Discover this node\'s neighbors here.\n}',
'The queue determines traversal order.|Set.add returns false for an already-seen value.|The duplicate check prevents cyclic graphs from looping indefinitely.',
'A graph can contain cycles even when a machine layout looks like a simple line.',
'Which collection best answers “have I already visited this position?”',['ArrayList with duplicate entries','HashSet','A single int','StringBuilder'],1,'A set models unique membership directly. It is a natural visited collection for graph traversal.',java),
L(2,'classes','Classes, instances, and ownership','Place per-machine state on the instance that owns it.',
'A class defines a type. An instance is one object of that type with its own fields. Constructors initialize those fields and can reject impossible starting states. The this keyword refers to the current instance and distinguishes a field from a parameter with the same name.|A common modding bug is making a machine inventory or progress counter static. Static fields belong to the class, so all instances share them. In Minecraft, the registered block object itself is also shared across placements. Position-specific state belongs in a block entity, not a field on the registered block.',
'final class Buffer {\n    private final int capacity;\n    private int stored;\n\n    Buffer(int capacity) {\n        if (capacity <= 0) throw new IllegalArgumentException();\n        this.capacity = capacity;\n    }\n}',
'Each new Buffer has its own stored field.|final prevents capacity from being reassigned after construction.|private limits mutation to code inside the class.',
'A shared block definition is not one placed machine.',
'Two placed machines need independent progress. Where should it live?',['A static field','A field on the shared registered block','Each machine’s block entity','A texture file'],2,'A block entity represents position-specific persistent state. Static fields and shared block objects cannot model independent machine progress.',java),
L(2,'encapsulation','Encapsulation and valid state','Expose operations instead of unrestricted mutable fields.',
'A public stored field allows any caller to assign an impossible value. Encapsulation gives the owning object control over changes. An insert method can accept only the amount that fits and report how much it accepted. Callers do not need to know how storage is represented.|A useful operation has a precise contract: insert returns the accepted amount, leaves the remainder with the caller, and never exceeds capacity. Define that contract before implementation. The same idea later applies to inventory transactions and network requests.',
'int insert(int amount) {\n    if (amount <= 0) return 0;\n    int accepted = Math.min(amount, capacity - stored);\n    stored += accepted;\n    return accepted;\n}',
'A nonpositive request does nothing.|The minimum enforces remaining capacity.|The caller receives the accepted amount rather than guessing from state.',
'Returning the requested amount when only part fits can silently destroy items.',
'A buffer has room for 7 units and receives 12. What should insert return?',['12','5','7','0'],2,'It accepted 7. The caller retains 5. This makes conservation explicit.',java),
L(2,'interfaces','Interfaces as capability contracts','Depend on behavior instead of concrete machine classes.',
'An interface specifies operations a type supports. Code consuming an interface can work with different implementations without a chain of instanceof checks. A motor and a water wheel may both implement a power-source contract while obtaining power in completely different ways.|Keep interfaces small and meaningful. A consumer generally needs available power, not every setting of the source. Explicit contracts make future content additions less invasive. Do not build an enormous inheritance tree just because several objects look similar.',
'interface PowerSource {\n    int availableCapacity();\n}\n\nfinal class Motor implements PowerSource {\n    @Override\n    public int availableCapacity() { return 128; }\n}',
'The interface declares behavior without choosing storage.|implements promises to provide that behavior.|@Override lets the compiler check that the method matches the contract.',
'An interface does not automatically enforce the meaning of a returned value; document units and limits.',
'What is the main benefit of accepting PowerSource rather than Motor?',['The method only works on motors','The caller can use any implementation of the contract','Interfaces automatically save data','The JVM skips type checks'],1,'The caller depends on a capability. Other power sources can implement the same contract.',java),
L(2,'composition','Composition and state machines','Model machine behavior as explicit transitions.',
'Composition means an object contains collaborating components: an inventory, a recipe processor, and a power connection. Each component owns a smaller responsibility. This is often more flexible than subclassing a giant base machine for every variation.|A state machine names the states and defines legal transitions. IDLE may become RUNNING when all prerequisites hold, RUNNING becomes BLOCKED if output cannot fit, and completion returns to IDLE. Derive states from authoritative data where possible rather than storing multiple booleans that can contradict each other.',
'enum MachineState { IDLE, RUNNING, BLOCKED }\n\nstatic MachineState state(boolean hasRecipe, boolean outputFits) {\n    if (!hasRecipe) return MachineState.IDLE;\n    if (!outputFits) return MachineState.BLOCKED;\n    return MachineState.RUNNING;\n}',
'An enum restricts the vocabulary to known states.|Priority is explicit: no recipe means idle.|The result can drive sound and animation without owning inventory changes.',
'Independent isRunning and isBlocked booleans can both become true unless every transition is careful.',
'Why derive presentation state from machine data?',['To avoid contradictory duplicate state','To remove the need for server logic','To guarantee higher FPS','To avoid all enums'],0,'A single authoritative source avoids flags drifting out of sync.',java),
L(3,'toolchain','Set up the 26.3 toolchain','Use one verified version set from game to JDK.',
'This course targets Minecraft Java 26.3 with Java 25 and the unobfuscated game names. The course reference set is Fabric Loader 0.19.5, Fabric API 0.160.5+26.3, Loom 1.17.19, and Gradle 9.6.0, matching inspected local projects. These are pinned course inputs, not a claim that every value is the latest release.|Install a JDK, not just a runtime. Configure the IDE’s Gradle JVM and project SDK consistently. Use the project wrapper rather than a random global Gradle installation. Check java -version and the wrapper’s version output before debugging source errors. An old Yarn tutorial may describe a different naming and build pipeline.',
'java -version\n.\\gradlew.bat --version\n.\\gradlew.bat tasks\n.\\gradlew.bat build',
'java reports the active executable.|The wrapper reports its own Gradle and JVM.|tasks reveals available development commands before you assume their names.',
'Changing JAVA_HOME does not necessarily change an IDE’s configured Gradle JVM.',
'Which JDK is the course’s 26.3 target?',['Java 8','Java 17','Java 21','Java 25'],3,'The inspected 26.3 projects target Java 25. Keep both compilation and the game launch aligned.',migration,'shell'),
L(3,'gradle','Understand the build file','Read dependencies as reproducible inputs.',
'Gradle describes how to resolve dependencies, compile source, process resources, and package artifacts. Loom connects those tasks to the Minecraft development environment. Each coordinate identifies a dependency artifact and an exact version.|For this target, the build uses the unobfuscated Fabric Loom plugin and implementation dependencies. Do not paste a mappings dependency from an old Yarn-based build without checking the target. Keep a working baseline under version control and change one dependency at a time so failures have an identifiable cause.',
"plugins { id 'net.fabricmc.fabric-loom' version '1.17.19' }\ndependencies {\n    minecraft 'com.mojang:minecraft:26.3'\n    implementation 'net.fabricmc:fabric-loader:0.19.5'\n    implementation 'net.fabricmc.fabric-api:fabric-api:0.160.5+26.3'\n}\njava {\n    sourceCompatibility = JavaVersion.VERSION_25\n    targetCompatibility = JavaVersion.VERSION_25\n}",
'The plugin provides Minecraft-aware development tasks.|minecraft selects the exact game.|Fabric Loader and Fabric API are separate dependencies.',
'A successful dependency download does not establish runtime compatibility.',
'What makes a build easier to reproduce?',['Use + for every version','Pin inputs and keep the wrapper','Delete the lockfile before each run','Copy JARs into random directories'],1,'Pinned dependencies and a checked-in wrapper reduce differences between machines.',migration,'groovy'),
L(3,'debugging','Read a failure like an engineer','Find the first relevant cause and reproduce it.',
'A stack trace records the calls leading to failure. Start with the exception type and message, follow caused-by sections, then locate the first relevant frame in your code. The final “process exited” line rarely explains the actual defect.|Use a breakpoint to inspect values before the failing operation. Form one hypothesis, make the smallest change that addresses it, and rerun the same reproduction. A compiler error, resource loading error, dedicated-server crash, and native graphics failure are different problems and need different evidence.',
'// Break here before indexing:\nint slot = selectedSlot;\nif (slot < 0 || slot >= inventory.size()) {\n    throw new IllegalArgumentException("Invalid slot: " + slot);\n}\nItemStack stack = inventory.get(slot);',
'Inspect the value of slot and the collection size.|The valid upper bound is exclusive.|Include relevant values in diagnostic messages.',
'Changing multiple unrelated things can hide the cause even when the crash disappears.',
'An inventory size is 9. Which index is invalid?',['0','4','8','9'],3,'The valid indices are 0 through 8. Index 9 is one past the end.',java),
L(3,'lifecycle','Entrypoints and lifecycle','Know when your code is called and on which side.',
'A mod initializer is called by Fabric; it is not a main method that replaces Minecraft’s loop. Use initialization to register content and callbacks. Ongoing behavior belongs in an appropriate callback or tick function, not an infinite loop inside the initializer.|Common code must be loadable on a dedicated server. Client rendering and input belong behind a client entrypoint. Single-player still has a logical server, so “it worked in my single-player world” is not sufficient evidence that your separation is correct.',
'package dev.biome;\n\nimport net.fabricmc.api.ModInitializer;\n\npublic final class BiomeMod implements ModInitializer {\n    @Override\n    public void onInitialize() {\n        // Register content and callbacks here.\n    }\n}',
'Fabric creates the initializer through metadata.|implements makes the entrypoint contract explicit.|The method returns after setup, allowing Minecraft to continue startup.',
'An infinite loop in onInitialize prevents the game from finishing initialization.',
'Where should client renderer registration happen?',['A server-only entrypoint','Inside a constructor for every item','A client entrypoint','An infinite initializer loop'],2,'Client-specific registration belongs in client initialization to keep common code dedicated-server safe.'),
L(4,'identifiers','Identifiers and registries','Give content stable names that saves can reference.',
'A registry connects a stable identifier to a game object. An identifier has a namespace and a path, such as biome:alloy_plate. Your namespace distinguishes your content from vanilla and other mods. The path becomes part of recipes, tags, models, commands, and saved data.|Display names are translations and can change freely. Registry identifiers require more care because worlds can already contain them. In 26.3, inspect the current Identifier and ResourceKey usage rather than copying old ResourceLocation or Yarn Identifier constructors.',
'Identifier id = Identifier.fromNamespaceAndPath("biome", "alloy_plate");\nResourceKey<Item> key = ResourceKey.create(Registries.ITEM, id);\nItem plate = new Item(new Item.Properties().setId(key));\nRegistry.register(BuiltInRegistries.ITEM, id, plate);',
'The identifier is the persistent name.|The typed key identifies the item registry entry.|The item properties receive the key before registration.',
'Renaming a registry ID is a save migration problem, not merely a text edit.',
'Which can usually be renamed without changing saved item identity?',['Registry namespace','Registry path','Localized display name','Serialized item ID'],2,'The translation displayed to players is separate from the stable registry identity.'),
L(4,'items','An item’s complete resource chain','Connect a registered item to its visible presentation.',
'Registration creates the game object but does not supply artwork or a localized name. A complete item has metadata, an item definition, a model, texture references, and language entries. Debug missing visuals by following those references from the identifier outward.|Keep client assets in assets/<namespace> and server data in data/<namespace>. Resource names are case-sensitive in the packaged mod even if your local filesystem is forgiving. Validate the built JAR as well as the source tree: missing processResources inputs can create a development-only success.',
'assets/biome/\n  items/alloy_plate.json\n  models/item/alloy_plate.json\n  textures/item/alloy_plate.png\n  lang/en_us.json\n\ndata/biome/\n  recipe/alloy_plate.json',
'The item definition selects presentation.|The model references the texture.|The recipe lives in server data, not alongside textures.',
'A pink-and-black texture usually points to a resource chain problem, not a broken item registry.',
'Which directory holds recipes?',['assets/biome/textures','data/biome/recipe','src/main/java/assets','assets/minecraft/lang'],1,'Recipes are server data. The singular recipe directory is the course target’s convention.',fabric,'text'),
L(4,'blocks','Blocks and block items','Distinguish a world block from its inventory representation.',
'A block defines behavior for positions in the world. A block item is the inventory object that places that block. Registering only the block does not automatically create an item players can hold. Both entries have their own registry keys even when they share the same textual identifier.|A complete block also needs blockstate-to-model mapping, model and texture resources, an appropriate loot table, and relevant mining tags. Test placement and survival breaking separately: a block can look correct in creative mode but drop nothing in survival.',
'// Conceptual registration order:\n// 1. Create a BLOCK key and properties with that key.\n// 2. Construct and register the block.\n// 3. Create an ITEM key and properties with that key.\n// 4. Construct BlockItem with the registered block.\n// 5. Register the BlockItem in the item registry.',
'World behavior and inventory behavior are separate objects.|Create the block before the item that refers to it.|Resources and drops complete the player-facing feature.',
'Creative-mode placement does not test loot tables or tool requirements.',
'What lets a player hold a placeable custom block in inventory?',['Its blockstate JSON alone','A BlockItem','A translation key','A server tick event'],1,'The BlockItem is the inventory representation and placement behavior.'),
L(4,'data-driven','26.3: data and components','Recognize when behavior moved out of older Fabric registries.',
'In 26.3, several older Fabric registration APIs are gone. Fuel and composting behavior uses item components; brewing recipes are data-driven. Before porting code, identify whether the feature is now described through data or components instead of trying to recreate a removed callback.|Treat recipe and component definitions as code: give them review, validate their target schema, and test the gameplay outcome. Use vanilla target-version examples or data generation as a schema reference. An older tutorial can still explain a concept while its exact API no longer applies.',
'// Migration checklist for 26.3:\n// FuelRegistry -> item fuel component\n// CompostingChanceRegistry -> compostable component\n// Brewing builder -> recipe data\n// Block transform registries -> transformer data/helpers',
'First identify the removed extension point.|Then inspect the replacement in the exact target.|Verify behavior in-game after compilation.',
'A guessed JSON field can silently invalidate a resource; use matching schemas.',
'An old guide uses FuelRegistry. What should you do for 26.3?',['Copy it unchanged','Use the current fuel component mechanism','Add a fake class named FuelRegistry','Downgrade the game without checking'],1,'The 26.3 migration notes document the component-based replacement.',migration),
L(5,'blockstates','Block states versus block entities','Keep finite visible properties separate from mutable data.',
'A block state is an immutable combination of declared properties, such as facing and powered. Changing one property creates a new state value; it does not mutate the old object. The property set should stay small because combinations multiply.|An inventory, an owner UUID, or a large progress counter is not a good blockstate property. Store that data in a block entity. Use block states for a small set of values the world and model system need to know directly, and synchronize additional presentation data separately.',
'// Architectural sketch: API names depend on the property.\n// current = level.getBlockState(position)\n// next = current with FACING changed\n// level.setBlock(position, next, appropriate update flags)',
'Read the current state so unrelated properties survive.|Construct a replacement state.|Notify the world using the appropriate update behavior.',
'Four booleans already produce 16 combinations; adding a 16-value property raises that to 256.',
'Which belongs in a block entity?',['Facing direction','A powered boolean','An inventory of ItemStacks','A small axis enum'],2,'Inventory contents are mutable, potentially large per-position data.'),
L(5,'sides','The server owns gameplay','Separate authoritative changes from visual feedback.',
'The logical server owns world changes, inventory consumption, damage, and machine results. The client presents information and sends requests. Single-player has both logical sides, which is why running the same mutation on both sides can create misleading results.|Design each interaction in three steps: determine intent, validate it on the server, and perform the authoritative change. Then send or expose the minimum information needed for presentation. A client animation can begin immediately, but the server still decides whether the action actually happened.',
'// Interaction design:\n// Client: request the chosen machine mode.\n// Server: validate player, position, distance, and mode.\n// Server: update machine state once.\n// Client: display synchronized state.',
'Intent is not proof that an operation is valid.|The server performs the mutation.|Presentation follows the authoritative result.',
'Testing only an integrated server can hide accidental client-only dependencies.',
'Who should decide whether an input item is consumed?',['Every client independently','Only the logical server','The renderer','The language resource file'],1,'The server is authoritative for gameplay and inventory state.'),
L(5,'interaction','Design a precise interaction','Define success, rejection, and item conservation.',
'An interaction should distinguish handled success, deliberate rejection, and passing through to other behavior. Check the held item, permissions, and machine state before mutation. Offhand behavior also matters: one physical click can reach multiple interaction paths.|Specify what happens to containers, durability, sounds, and creative-mode items. For example, filling a tank should account for both the water and its bucket. Think through a full player inventory and a failed operation. A clear precondition-and-result contract is easier to test than scattered side effects.',
'// Transfer contract:\n// Preconditions: allowed player, supported item, enough room.\n// Success: transfer exactly N, exchange the container once.\n// Failure: change neither side.\n// Feedback: one sound, one state update.',
'Preconditions are checked before either inventory changes.|Successful mutation has a defined amount.|Failure preserves both source and destination.',
'Playing a sound on both client and server can duplicate feedback.',
'A transfer is rejected because the destination is full. What changes?',['The source still loses its item','Nothing in either inventory','Only the output count','The recipe is completed anyway'],1,'A rejected operation must preserve the source and destination.'),
L(5,'events','Events before mixins','Choose the least invasive extension point.',
'A Fabric event exposes a supported point for adding behavior. A mixin modifies an existing class and is useful when no suitable extension point exists, but its target is more tightly coupled to implementation details. Prefer the smallest intervention that expresses the feature.|Before writing a mixin, inspect the event’s contract: when it runs, which side calls it, what its return value means, and whether it can cancel vanilla behavior. A callback that observes an event is different from a hook that replaces the underlying operation.',
'// Decision sequence:\n// Existing data mechanism? Use data.\n// Existing component/property? Use that contract.\n// Supported event? Register a focused callback.\n// No suitable hook? Inspect an exact mixin target.',
'Data-driven behavior is often the least invasive.|Events preserve a stable extension boundary.|Mixins require target-version verification.',
'Injecting at every method return can trigger more often than the conceptual player action.',
'When is a mixin justified?',['Whenever you want fewer files','When no suitable supported extension point covers the behavior','For every new item','Only for textures'],1,'A mixin is a targeted tool for gaps in available extension points, with compatibility costs.'),
L(6,'block-entities','A machine’s persistent instance','Connect a placed block to its stored machine data.',
'A block entity holds data for a particular block position. Its type must be registered and associated with the blocks that can create it. The block provides construction, while the block entity owns inventory, progress, and other per-instance fields.|Do not perform world operations in the constructor before the level reference is available. Keep construction limited to establishing valid initial state. Lifecycle hooks and ticks can then operate with a real world context. Breaking and replacing the block must account for its stored contents.',
'// Per-machine fields, not static fields:\nprivate int progress;\nprivate int storedEnergy;\nprivate final List<ItemStack> inventory;\n\n// Block entity creation belongs to the block/type contract.\n// World-dependent work belongs after attachment to a level.',
'Each placement has independent fields.|The registered type describes how to reconstruct instances.|Inventory ownership determines drop and save behavior.',
'A constructor can run before the instance is attached to a level.',
'Which field should normally be static?',['Machine progress','Stored energy','The registered block entity type','An inventory slot'],2,'The type registration is shared metadata. Machine state is per instance.'),
L(6,'ticking','Ticking without wasting work','Make each tick bounded and conditional.',
'A machine tick advances its simulation. Avoid scanning the whole world, searching every recipe, or rebuilding an entire network every tick. First decide whether the machine can work. If it cannot, keep the path cheap and preserve the correct paused state.|Define progress in ticks or in explicit work units. Decide whether loss of power pauses progress or resets it. The policy must be consistent across save/load and synchronization. Minecraft aims for 20 ticks per second, but wall-clock completion time increases when the server falls behind.',
'static int advance(int progress, boolean canWork, int duration) {\n    if (!canWork) return progress;\n    return Math.min(progress + 1, duration);\n}',
'A blocked machine retains its work.|A running machine advances one unit.|The result never exceeds the duration.',
'Twenty game ticks are not a guaranteed wall-clock second on an overloaded server.',
'Where should an expensive network rebuild usually happen?',['Every render frame','Only when relevant topology changes','For every inventory slot every tick','Inside a translation file'],1,'Invalidate on relevant changes and reuse a valid result between changes.'),
L(6,'persistence','Saving is a separate responsibility','Persist state without confusing it with synchronization.',
'Changing a field in memory does not guarantee that the change will survive a world reload. Persist the fields needed to reconstruct the machine, and mark persistent changes appropriately so the game knows the data is dirty. Save only authoritative state; caches can often be rebuilt.|For 26.3, inspect ValueInput and ValueOutput-based methods in the resolved block entity source. Do not paste older NBT overrides and assume they will be called. Missing fields need safe defaults so older saves can still load. Loading should also clamp or validate values before using them.',
'// Save format design:\n// formatVersion: 1\n// progress: nonnegative integer\n// storedEnergy: 0..capacity\n// inventory: serialized item stacks\n// Rebuild cached recipe and network membership after load.',
'The save schema identifies authoritative fields.|Defaults handle older data.|Derived caches are reconstructed rather than trusted blindly.',
'Marking data dirty and sending a client update solve different problems.',
'What does a client update packet prove about persistence?',['That the chunk is saved','That every future load will work','Nothing by itself','That the save schema is migrated'],2,'Network synchronization and disk persistence are independent responsibilities.'),
L(6,'inventory','Inventory ownership and slot rules','Make insertion and extraction rules explicit.',
'A machine inventory needs rules for each slot: accepted input, fuel, output, or upgrades. Validate both manual interaction and automation. A rule enforced only by the screen can be bypassed by a hopper or another mod calling the inventory API.|ItemStack values are mutable. Know when you are holding a reference to the inventory’s stack and when you need a copy. Return values must reflect exactly what moved. On block removal, drop owned contents once and avoid running that logic merely because the same block changed state.',
'// Suggested slot contract:\n// 0: input; external insertion allowed if recipe-compatible\n// 1: output; external insertion rejected\n// 2: fuel; insertion restricted to supported fuel\n// Extraction rules apply to automation as well as the menu.',
'Slot roles are part of the machine contract.|Validation belongs below the UI.|Break handling must distinguish replacement from property changes.',
'Mutating a copied stack does not change the inventory unless you commit the replacement.',
'Where should slot restrictions be enforced?',['Only in button labels','At the inventory/transfer boundary','Only in the texture','Only in the client screen'],1,'Every insertion path must honor the same inventory rules.'),
L(7,'recipes','Recipes as data','Separate processing rules from machine mechanics.',
'A recipe describes inputs, outputs, and processing requirements. A machine executes that rule. Keeping those concerns separate lets data packs add recipes without creating a new machine class. A recipe cache must be invalidated when inputs change or resources reload.|For custom recipe systems, define the schema and codec contract deliberately. Reject impossible durations and amounts at loading boundaries. Work from target-version registry and recipe examples; 26.3 changed reloadable registry behavior. Keep the machine’s execution algorithm independent of individual item IDs.',
'// Recipe contract (conceptual, not a vanilla JSON schema):\n// input ingredient + count\n// output item + count\n// processing duration\n// power requirement\n// optional byproduct\n// stable recipe identifier',
'Ingredient matching is separate from execution.|Output capacity is checked before committing.|Reload invalidates recipe references.',
'A stale cached recipe may no longer exist after a data-pack reload.',
'What should happen to cached recipe matches after a reload?',['Keep them forever','Invalidate and resolve them again','Delete the player inventory','Change every registry ID'],1,'The definitions may have changed. Re-resolve against the new authoritative data.'),
L(7,'transactions','Conservation and atomic transfers','Prevent duplication and loss across partial failures.',
'A transaction treats multiple related changes as one operation. For processing, removing input and inserting output must agree. If the output cannot be accepted, do not consume input. For a multi-step transfer, simulation can establish feasibility before a final commit.|Be precise about partial acceptance. If a destination can hold three of five items, either move three and leave two, or reject the entire batch according to the contract. Both policies can be valid; reporting five while moving three is not. Recheck assumptions at the boundary where the mutation becomes authoritative.',
'static int transferable(int requested, int sourceCount, int freeSpace) {\n    if (requested <= 0) return 0;\n    return Math.max(0, Math.min(requested, Math.min(sourceCount, freeSpace)));\n}',
'The request caps the intended amount.|Source availability caps what exists.|Destination space caps what can be accepted.',
'A simulation must not itself mutate inventory.',
'Source has 8, destination fits 3, request is 5. How many can transfer?',['8','5','3','0 in all designs'],2,'With partial transfer allowed, the amount is min(5, 8, 3), which is 3.'),
L(7,'automation','Hoppers and sided access','Expose useful automation without bypassing rules.',
'Sided access means a transfer can behave differently depending on the face. A top face might accept inputs while the bottom exposes outputs. Document the convention and make it visible through tooltips or design. Players should not have to guess which face does what.|Keep the side adapter thin: it delegates to the same core inventory rules as manual use. Avoid maintaining a second shadow inventory for automation. Test full outputs, invalid items, partial stacks, and simultaneous machine processing with external extraction.',
'// Example access policy:\n// TOP: insert input\n// BOTTOM: extract output\n// SIDES: insert fuel\n// All faces: reject insertion into the output slot.',
'A face determines which operation is exposed.|The underlying inventory remains authoritative.|UI and automation share validation.',
'Sided rules implemented only in the menu do not control hoppers.',
'Why avoid a separate “hopper inventory” copy?',['It always uses too much RAM','Copies can diverge from authoritative contents','Hoppers do not move items','Java forbids two lists'],1,'Diverging inventories can cause inconsistent counts, loss, or duplication.'),
L(7,'redstone','Control and measurement','Use redstone for policy and comparators for observable state.',
'Redstone can enable, disable, or pulse a machine. Define the control mode explicitly. “Powered means stop” and “powered means run” are both reasonable policies, but the player must know which one applies. Edge-triggered actions need to distinguish a new pulse from a continuously powered state.|A comparator can expose fullness or progress using a bounded signal from 0 to 15. Update neighbors when the observable signal changes rather than spamming updates for invisible internal changes. Keep the conversion function separate so boundaries are easy to test.',
'static int signal(int stored, int capacity) {\n    if (capacity <= 0 || stored <= 0) return 0;\n    return Math.min(15, 1 + (14 * stored / capacity));\n}',
'Empty storage produces zero.|Nonempty storage produces at least one.|The clamp prevents values above the valid redstone range.',
'Level-triggered behavior can repeat every tick while power remains on.',
'A one-shot action should fire when power changes from…',['On to on','Off to on','Any value to itself','A texture to a model'],1,'A rising edge is the transition from unpowered to powered.'),
L(8,'payloads','Requests across a network','Send intent with a small, explicit payload.',
'A network payload is a structured message. Define its identifier, field types, and encoding consistently at both ends. Keep it small: a player changing a machine mode normally sends a position and requested mode, not the entire world or a replacement inventory.|Separate client-to-server requests from server-to-client state. The server handler validates the request in the correct execution context before touching world data. A payload decoder establishing that an integer can be read does not prove that the integer is a valid mode.',
'// Client -> server request:\n// position: the machine the player is using\n// requestedMode: one allowed enum value\n// Server -> client update:\n// accepted authoritative mode and needed display state',
'Encoding defines the message shape.|Validation defines whether it is allowed.|Only accepted state is synchronized back.',
'Never trust a client-provided “new inventory” as authoritative state.',
'What should a mode-change request contain?',['The entire player save','Intent sufficient for the server to validate','A guaranteed permission flag','A new inventory to accept blindly'],1,'Clients request operations. The server decides whether and how to perform them.'),
L(8,'validation','Validate at the server boundary','Check identity, distance, state, and limits.',
'Treat every client request as untrusted input. Verify that the sender is allowed to act, the target exists in a loaded area, the block entity has the expected type, the player is close enough, and the requested value is within range. Do not load distant chunks merely because a client named a position.|Validation must use server state, not a boolean supplied by the client. Repeated expensive requests also need bounds. A small payload can still trigger an expensive search if the handler is careless.',
'static boolean allowed(double distanceSquared, int mode, boolean ownsMachine) {\n    return ownsMachine && distanceSquared <= 64.0\n        && distanceSquared >= 0.0 && mode >= 0 && mode < 3;\n}',
'Squared distance avoids a square-root operation.|The mode range is explicit.|Ownership is obtained from server state before this pure decision.',
'A client-provided ownsMachine value is not an authorization check.',
'Where must an ownership check obtain its facts?',['From a client checkbox','From authoritative server state','From the packet’s display text','From the current texture'],1,'The server must independently establish ownership or permission.'),
L(8,'sync','Synchronize only what is needed','Keep rendering state current without sending everything.',
'Clients need enough state to draw the machine and its menu, not every server cache. Initial synchronization handles a player first seeing the chunk or opening the menu. Incremental updates handle later changes. Both paths must agree on the meaning of fields.|Choose an update cadence based on visible need. A progress bar may tolerate periodic snapshots and interpolation. An inventory change needs accurate slot synchronization. Send updates on meaningful changes and test a second client joining after the machine is already running.',
'// Synchronization checklist:\n// Initial chunk visibility\n// Menu opening\n// Changed mode or inventory\n// Periodic progress snapshot if needed\n// Reconnect and late join',
'Initial state is not automatically covered by later updates.|Different fields have different accuracy needs.|Late join is a separate test case.',
'A machine can look correct for its creator while remaining stale for late joiners.',
'Which test catches missing initial synchronization?',['Only watching the placing player','Joining after the machine starts','Recompiling the JAR','Changing a language entry'],1,'A late joiner must receive the current state without relying on past updates.'),
L(8,'menus','Menus and screens have different jobs','Keep inventory authority out of client presentation.',
'A server-side menu coordinates slots and synchronized properties. A client screen draws widgets and sends intent. The screen does not become authoritative just because the player can click a slot. Shift-click behavior needs explicit transfer ranges and the same item restrictions as other paths.|Treat menu closing, block removal, player distance, and disconnects as normal lifecycle events. Temporary crafting inputs must be returned or dropped according to a defined rule. Test full inventories and cursor-held stacks when closing.',
'// Server menu: slot ownership, transfer rules, validity.\n// Client screen: layout, labels, input focus, rendering.\n// Shared protocol: slot updates and validated actions.',
'The server owns item movement.|The screen presents and requests.|Closing paths must account for every owned item.',
'A screen-only restriction can be bypassed by a modified client.',
'Where should shift-click transfer rules live?',['Only in the rendered button','In server menu/inventory logic','In a PNG','In the language file'],1,'The server must enforce item movement regardless of the client UI.'),
L(9,'models','Models and resource diagnosis','Trace a missing model through its references.',
'Treat a visual resource as a dependency chain: blockstate or item definition, model, texture, and optional animation metadata. Read the resource reload log and verify exact namespaces and paths. An item model and a world block model can have different entry points.|Keep a simple known-good model while debugging behavior. Once registration and resource resolution are correct, add custom geometry. Check the final packaged resources and test resource reload, not just a fresh launch.',
'// Diagnose in order:\n// 1. Is the registered ID correct?\n// 2. Does its definition exist in the built JAR?\n// 3. Does the referenced model resolve?\n// 4. Do all referenced textures resolve?\n// 5. Does reload report a schema or path error?',
'Start at the content identifier.|Follow each reference exactly.|Validate packaging and reload separately.',
'A working source-tree asset may still be omitted from the release JAR.',
'Which is the strongest packaging check?',['The PNG exists somewhere on disk','The expected resource is inside the built JAR','The IDE shows a green icon','The filename contains the mod name'],1,'The game loads the packaged artifact users install.'),
L(9,'rendering','Render state and presentation','Keep rendering separate from world mutation.',
'Rendering reads state to produce a frame. It must not consume input, complete recipes, or change authoritative progress. Frame rate varies independently from simulation tick rate, so gameplay performed in a renderer would behave differently on different computers.|The 26.3 rendering pipeline is version-sensitive. Inspect current renderer contracts and keep client classes in the client source set or entrypoint. Cache only data whose lifetime you understand and release references when the world changes.',
'// Simulation produces: angle, active state, progress.\n// Presentation reads: a snapshot of those values.\n// Rendering produces: geometry and visual effects.\n// It does not produce: inventory changes or recipe results.',
'Simulation and presentation have different clocks.|Snapshot data prevents accidental ownership confusion.|Client classes must not load on the dedicated server.',
'A 144 FPS client must not process recipes faster than a 30 FPS client.',
'Why must gameplay not depend on render calls?',['Rendering is always slow','Frame rate differs across clients','Java has no render methods','All servers have monitors'],1,'Simulation must remain consistent regardless of client frame rate.'),
L(9,'interpolation','Smooth motion between ticks','Interpolate presentation without inventing server state.',
'Interpolation blends two known samples for display. For a scalar value, linear interpolation is previous + (current - previous) * alpha, where alpha is between zero and one. This can smooth a moving part between simulation updates.|Angles require extra care because crossing from 359 degrees to 1 degree should normally move through the short two-degree arc. Normalize angular differences before interpolation. Visual prediction and authoritative gameplay are different concerns: smoothing must never grant extra processing work.',
'static double lerp(double previous, double current, double alpha) {\n    return previous + (current - previous) * alpha;\n}',
'alpha 0 returns the previous sample.|alpha 1 returns the current sample.|Values between them blend linearly.',
'Naive angle interpolation may spin almost a full turn at the wrap boundary.',
'What is lerp(10, 20, 0.25)?',['10','12.5','15','25'],1,'10 + (20 - 10) × 0.25 equals 12.5.',java),
L(9,'input','26.3 input and accessibility','Use current input abstractions and respect focus.',
'Minecraft 26.3 moved its window/input backend to SDL. Code copied from a GLFW-based tutorial can refer to the wrong constants or assume behavior that no longer exists. Use Minecraft’s current input abstractions instead of hardcoded backend numbers.|Custom text fields need correct focus handling so typing reaches the intended widget. Check keyboard navigation, resizing, readable contrast, and remapped controls. A shortcut should not activate while the user is typing into a text field unless that is explicitly intended.',
'// Input test plan:\n// Rebind the action.\n// Focus and unfocus a text field.\n// Type non-ASCII text.\n// Navigate using the keyboard.\n// Resize the window and increase UI scale.',
'Use semantic game input rather than backend magic numbers.|Focus is part of the input contract.|Accessibility tests reveal real layout and interaction defects.',
'Hardcoding an old GLFW mouse constant is not a reliable 26.3 input strategy.',
'Which approach survives backend changes best?',['Hardcoded mouse integers','Minecraft’s supported input abstraction','Copying GLFW imports blindly','Ignoring text-field focus'],1,'Game-level abstractions reduce coupling to the underlying window library.',migration),
L(10,'graphs','A machine network is a graph','Model connectivity independently of rendering.',
'A graph consists of nodes and edges. In a mechanical network, a node might be a machine or shaft connection, and an edge describes a valid connection between ports. Physical adjacency alone is not enough: two neighboring shafts may have incompatible axes.|Define connection rules symmetrically and test them independently. A traversal uses a queue or stack plus a visited set. Bound the work and avoid loading chunks during a search. Keep positions dimension-aware if your graph can span multiple worlds.',
'// Breadth-first traversal sketch:\n// queue <- start\n// while queue has work:\n//   node <- remove first\n//   if already visited: continue\n//   mark visited\n//   enqueue valid, loaded neighbors',
'Ports determine edges.|Visited membership handles cycles.|Loaded-boundary checks prevent accidental world expansion.',
'A network cache that holds strong references to unloaded worlds can leak memory.',
'What prevents infinite traversal around a loop of shafts?',['More textures','A visited set','A higher speed','A larger recursion limit'],1,'Each node is processed once when visited membership is checked.'),
L(10,'rotation','Propagating rotation and ratios','Carry direction and ratio through connected components.',
'Rotation propagation carries more than an on/off state. Each connection can preserve direction, reverse it, or change the ratio. Represent the relationship explicitly so a path from the source predicts the speed at each node.|Cycles create a consistency problem: two paths to the same node must imply compatible speeds. If one path predicts 32 RPM and another predicts 64 RPM, the network needs a defined conflict policy. Do not let traversal order decide the result. Floating-point comparisons require a tolerance when ratios are not exact.',
'static double drivenSpeed(double sourceSpeed, double ratio, boolean reverse) {\n    double speed = sourceSpeed * ratio;\n    return reverse ? -speed : speed;\n}',
'Magnitude follows the ratio.|Sign represents direction in this simplified model.|Conflicting path predictions must be detected separately.',
'An inconsistent loop should produce a deterministic conflict result, not random speed changes.',
'A 32 RPM source drives a reversing 0.5 ratio. Output?',['64 RPM','16 RPM','-16 RPM','-64 RPM'],2,'32 × 0.5 gives magnitude 16; reversal changes the sign.'),
L(10,'stress','Capacity, demand, and overload','Make the network’s work budget explicit.',
'An engineering game can model mechanical load with an abstract capacity budget rather than a complete physical simulation. Sources provide capacity and active consumers demand it. The network operates only if demand is within capacity according to its chosen policy.|Decide whether idle or blocked machines count toward demand. Compute from a consistent snapshot so iteration order does not change the outcome. Keep the balancing model distinct from real torque physics. A useful simplified system is one players can predict and diagnose.',
'static boolean canRun(int capacity, int demand) {\n    return capacity > 0 && demand >= 0 && demand <= capacity;\n}',
'A source is required even when demand is zero.|Exact equality is allowed.|Overload is an explicit state, not a partially applied update.',
'Treating a game balance metric as a physical torque simulation leads to misleading assumptions.',
'Capacity is 128 and active demand is 129. Under this policy…',['Everything runs','The network is overloaded','Capacity becomes 129 automatically','A random consumer gets free power'],1,'Demand exceeds the available budget, so the network does not run.'),
L(10,'topology','Invalidate, rebuild, recover','Handle splits, merges, clutches, and unloading.',
'A network changes when blocks are added or removed, ports rotate, a clutch disengages, or chunks unload. Cached membership is valid only until a relevant topology change. Mark affected data invalid and rebuild through a bounded work path.|Removing one edge can split a component into several networks. Adding an edge can merge sources with incompatible speeds. Test both cases and clear stale membership. Never assume that the network that existed last tick still owns every node this tick.',
'// Topology events:\n// place / break\n// rotate a connection\n// engage / disengage clutch\n// chunk load / unload\n// dimension or world shutdown',
'Each event can change connectivity.|Splits require discovering the new components.|Shutdown must release cached references.',
'A removed source must not continue powering nodes through a stale cache.',
'What should a disconnected machine do before its network is resolved?',['Keep cached power forever','Use a defined safe state','Create a source automatically','Force-load every neighboring chunk'],1,'A safe unresolved state prevents stale power from creating work.'),
L(11,'worldgen','26.3 world-generation structure','Use the current feature and material-rule organization.',
'World generation is data-heavy and version-sensitive. In 26.3, feature data uses worldgen/feature and former surface rules are material rules. Start with a small controlled feature and inspect generated terrain in newly generated chunks.|Changing a definition does not regenerate already-saved terrain. Use a disposable test world or travel to genuinely new chunks. Keep dimension and biome conditions explicit, and test boundaries so a feature does not appear in every biome unintentionally.',
'data/biome/worldgen/\n  feature/\n  material_rule/\n  material_condition/\n\n// Verify exact schemas against 26.3 vanilla data.\n// Use fresh chunks when checking generation.',
'Paths alone do not define a valid feature.|Exact target schemas are required.|Old chunks preserve previously generated terrain.',
'Seeing no change in an old chunk is not proof that your new worldgen data failed.',
'Where should you test a changed terrain-generation rule?',['Only inside an already generated house','In freshly generated chunks','Only in the inventory screen','Only by recompiling Java'],1,'Generation occurs when new terrain is created.',migration,'text'),
L(11,'migrations','Save compatibility and migrations','Evolve persistent data without silently losing player work.',
'A released save format becomes an interface to existing worlds. Add a format version when data may evolve. Define how old fields map to new fields and preserve defaults for absent values. Migration should be deterministic and safe to run on supported older data.|Never test destructive migration logic on the player’s only world copy. Keep fixtures representing older formats. Loading and saving repeatedly should not keep transforming the same data or duplicating contents. Preserve stable registry IDs unless an explicit migration handles the change.',
'// Load algorithm:\n// read format version (default to oldest supported)\n// decode the matching old schema\n// transform into the current in-memory model\n// validate ranges and invariants\n// save using the current schema',
'Version identifies the decoder.|Migration has one deliberate direction.|Validation happens before using loaded values.',
'Silently treating an unknown future format as an old one can destroy data.',
'What property should repeated load/save cycles preserve?',['Inventory contents and meaning','Ever-increasing item counts','A new random owner each time','Progress reset on every load'],0,'Repeated serialization should preserve the intended state rather than introduce drift.'),
L(11,'profiling','Measure before optimizing','Find actual costs and preserve behavior.',
'Optimization starts with a reproducible workload and a measurement. A network of ten machines and a network of ten thousand expose different costs. Record tick time, allocation, and the frequency of expensive operations. Average time alone can hide large spikes.|Change one bottleneck at a time and verify behavior again. Caching trades repeated work for invalidation complexity and memory. An optimization that produces stale recipes or leaked worlds is a correctness regression, even if a small benchmark becomes faster.',
'// Measurement plan:\n// Baseline: same world, same machine count, same inputs.\n// Measure: tick cost, allocations, rebuild frequency.\n// Change: one identified bottleneck.\n// Re-run: performance and correctness checks.',
'Controlled inputs make comparisons meaningful.|Measure the work you intend to improve.|Correctness remains part of the acceptance criteria.',
'A microbenchmark of a helper does not prove an entire mod is faster in-game.',
'What should happen before introducing a network cache?',['Assume graph code is slow','Measure repeated traversal cost','Remove all validation','Rename classes'],1,'Evidence identifies whether the cache addresses a real bottleneck.'),
L(11,'testing','Build a verification ladder','Distinguish compilation, launch, and gameplay evidence.',
'Different tests establish different facts. A pure Java unit test can validate a transfer calculation. A game test can exercise block interaction in a real world. A dedicated-server launch catches client-class leakage. A graphical session checks rendering and input. None substitutes for all the others.|Choose tests from failure risks: no duplication, save/reopen, late join, chunk unload, blocked output, and resource reload. Record the exact artifact and target version tested. A green build proves compilation and configured checks, not every gameplay claim.',
'// Suggested ladder:\n// pure logic tests\n// build + resource validation\n// dedicated-server launch\n// focused gameplay checks\n// save/reopen + multiplayer\n// graphical and input review',
'Start with fast checks for isolated logic.|Move to the runtime for integration behavior.|Tie evidence to the exact artifact.',
'Testing a source checkout is not the same as testing the JAR you distribute.',
'Which check specifically tests persistence?',['Only javac','Saving, closing, and reopening the world','Reading a texture','Counting source files'],1,'A real reopen verifies that data survived serialization and reconstruction.'),
L(12,'architecture','Plan a vertical slice','Build a complete feature before expanding its catalog.',
'A vertical slice carries one feature through every layer: content registration, acquisition, interaction, persistence, feedback, and validation. A processing machine that genuinely works is a stronger foundation than fifty registered blocks with unfinished behavior.|Write the player workflow and the technical contracts before building abstractions. Separate pure decisions from world integration. Keep dependencies directional so a recipe does not need to know the screen layout and a renderer does not own processing.',
'Player intent\n  -> validated interaction\n  -> machine state transition\n  -> inventory/persistence update\n  -> synchronized presentation\n  -> observable result',
'Every layer serves the same player workflow.|Boundaries make failures easier to locate.|Expansion reuses proven contracts.',
'A large class count is not evidence of a complete feature.',
'Which is a vertical slice?',['Fifty empty block classes','One obtainable, working, persistent machine','A title screen only','A folder full of unused interfaces'],1,'A vertical slice completes the workflow across technical layers.',fabric,'text'),
L(12,'integration','Integrate without hard dependencies everywhere','Keep optional compatibility at a defined boundary.',
'An integration should have a clear owner and an explicit dependency policy. If another mod is optional, common startup must not eagerly reference its absent classes. A small adapter can translate between your internal contract and the external API.|Version compatibility is evidence-based. Compile against the intended dependency, test with it present, and test its absence when supported. Document what the integration actually does. Similar names or mechanics do not establish binary compatibility with Create or another mod.',
'// Your machine contract\n//        |\n// Optional adapter module\n//        |\n// External mod API\n\n// Keep external classes out of unrelated core code.',
'The adapter contains coupling.|Optional absence is a supported execution path.|The exact external API version matters.',
'An optional metadata declaration does not make eager Java class loading safe.',
'Why isolate optional integration code?',['To make every dependency mandatory','To keep absent external classes from breaking core startup','To avoid testing','To hide source files'],1,'Isolation makes the missing-dependency path explicit and testable.'),
L(12,'packaging','Package the artifact users will install','Inspect metadata, resources, and dependencies.',
'The build output is what players use. Inspect the JAR for mod metadata, expected classes, resources, licenses, and accidental development-only files. Confirm declared Minecraft, Java, Loader, and mod dependencies match the target you actually tested.|Install the resulting artifact into a separate test instance. Development environments can include dependencies or resources that are missing from a release. Keep source archives distinct from installable JARs and do not distribute Minecraft binaries as part of your source project.',
'// Release inspection:\n// fabric.mod.json present and correct\n// common and client entrypoints resolve\n// assets/ and data/ included\n// no test worlds or credentials\n// declared dependencies match the tested target',
'Metadata controls loading.|Resources must be present in the artifact.|A separate install catches development-environment assumptions.',
'A sources JAR is not normally the file players should put in their mods folder.',
'Which artifact should be tested before release?',['Only loose source files','The exact installable JAR','A screenshot of the IDE','An older release with a similar name'],1,'The exact artifact is the only reliable subject for release claims.'),
L(12,'release','Ship with an honest compatibility contract','Describe what works, what was checked, and what remains.',
'A release should state its target version, required dependencies, installation path, implemented behavior, and known limitations. Keep a changelog focused on user-visible changes. If you change save behavior, explain migration and backup expectations clearly.|Do not label a build multiplayer-safe, optimized, or fully compatible without matching evidence. Record checks and reproducible failures. A useful release gives players enough information to decide whether it fits their world and gives you enough information to investigate reports.',
'Release record\n  Version and artifact hash\n  Supported game / Loader / API / Java\n  Implemented behavior\n  Checks performed on this artifact\n  Known limitations and migration notes',
'The artifact hash identifies what was checked.|Compatibility is scoped to actual evidence.|Known limitations help users make informed choices.',
'“Build succeeded” is not a synonym for “all gameplay verified.”',
'A build compiled but was never launched. Which claim is accurate?',['Fully gameplay tested','Compilation passed; runtime unverified','Guaranteed compatible with every mod','Multiplayer certified'],1,'Report the evidence you actually have without extending it to untested behavior.',fabric,'text'),
];

const E=(id,method,task,starter,solution,tests,hints)=>{Object.assign(lessons.find(l=>l.id===id),{exercise:{method,task,starter,solution,tests:tests.map(([args,expected,label])=>({args,expected,label})),hints},minutes:20})};
E('types','fillRatio','Return stored / capacity as a double. Return 0.0 when capacity is zero or negative.','static double fillRatio(int stored, int capacity) {\n    // Implement the contract.\n    return 0.0;\n}','static double fillRatio(int stored, int capacity) {\n    if (capacity <= 0) return 0.0;\n    return (double) stored / capacity;\n}',[[[3,4],0.75,'Fractional fill'],[[0,10],0,'Empty buffer'],[[5,0],0,'Zero capacity'],[[10,10],1,'Full buffer']],['Guard against capacity <= 0 before division.','Convert an operand to double before dividing.']);
E('methods','batchCost','Return count multiplied by costPerItem. Inputs are nonnegative and their product fits in int.','static int batchCost(int count, int costPerItem) {\n    return 0;\n}','static int batchCost(int count, int costPerItem) {\n    return count * costPerItem;\n}',[[[4,12],48,'Four-item batch'],[[0,12],0,'Empty batch'],[[7,9],63,'Different recipe'],[[1,128],128,'Single expensive item']],['Use the parameters; do not hardcode the example.','Return the multiplication directly.']);
E('guards','canExtract','Allow extraction only when requested is nonnegative and no greater than charge. charge is nonnegative.','static boolean canExtract(int charge, int requested) {\n    return false;\n}','static boolean canExtract(int charge, int requested) {\n    return requested >= 0 && requested <= charge;\n}',[[[40,40],true,'Exact amount'],[[40,41],false,'Insufficient charge'],[[40,-1],false,'Negative request'],[[0,0],true,'Zero extraction']],['Exact equality is allowed.','Both conditions must be true: use &&.']);
E('collections','sumDemand','Sum all nonnegative entries in an int[] named demand. Ignore negative entries. The sum fits in int.','static int sumDemand(int[] demand) {\n    return 0;\n}','static int sumDemand(int[] demand) {\n    int total = 0;\n    for (int value : demand) {\n        if (value >= 0) total += value;\n    }\n    return total;\n}',[[[[12,8,4]],24,'Three consumers'],[[[10,-4,2]],12,'Ignore invalid demand'],[[[]],0,'Empty network'],[[[0,128]],128,'Zero and active load']],['Initialize a total before the loop.','An enhanced for loop is: for (int value : demand).']);
E('encapsulation','accepted','Return how many units fit: between 0 and requested, limited by capacity - stored. Inputs stored/capacity are valid; negative requests accept zero.','static int accepted(int stored, int capacity, int requested) {\n    return 0;\n}','static int accepted(int stored, int capacity, int requested) {\n    if (requested <= 0) return 0;\n    return Math.min(requested, capacity - stored);\n}',[[[3,10,12],7,'Partial fit'],[[10,10,5],0,'Full buffer'],[[0,64,5],5,'Entire request'],[[2,10,-5],0,'Reject negative']],['Compute remaining capacity, not total capacity.','Math.min chooses the smaller of two values.']);
E('ticking','advance','If canWork is false, preserve progress. Otherwise increase by one, capped at duration. Inputs satisfy 0 <= progress <= duration.','static int advance(int progress, boolean canWork, int duration) {\n    return progress;\n}','static int advance(int progress, boolean canWork, int duration) {\n    if (!canWork) return progress;\n    return Math.min(progress + 1, duration);\n}',[[[5,true,20],6,'Working'],[[5,false,20],5,'Paused'],[[20,true,20],20,'Already complete'],[[0,true,20],1,'First tick']],['Return early for the paused case.','Clamp the new progress to duration.']);
E('transactions','transferable','Return a nonnegative transfer amount bounded by requested, sourceCount, and freeSpace. Source count and space are nonnegative.','static int transferable(int requested, int sourceCount, int freeSpace) {\n    return 0;\n}','static int transferable(int requested, int sourceCount, int freeSpace) {\n    return Math.max(0, Math.min(requested, Math.min(sourceCount, freeSpace)));\n}',[[[5,8,3],3,'Destination limited'],[[8,2,64],2,'Source limited'],[[2,8,64],2,'Request limited'],[[-3,10,10],0,'Negative request'],[[5,8,0],0,'No room']],['The smallest positive limit wins.','Clamp the result to at least zero.']);
E('redstone','signal','Map storage to comparator output: empty/invalid capacity gives 0; otherwise min(15, 1 + 14 * stored / capacity) using integer arithmetic.','static int signal(int stored, int capacity) {\n    return 0;\n}','static int signal(int stored, int capacity) {\n    if (capacity <= 0 || stored <= 0) return 0;\n    return Math.min(15, 1 + 14 * stored / capacity);\n}',[[[0,64],0,'Empty'],[[32,64],8,'Half full'],[[64,64],15,'Full'],[[1,64],1,'One item'],[[5,0],0,'Invalid capacity']],['Guard before division.','Integer division deliberately quantizes the signal.']);
E('validation','allowed','Allow only an owner within squared distance 0..64 inclusive, using mode 0, 1, or 2. Reject all other cases.','static boolean allowed(double distanceSquared, int mode, boolean ownsMachine) {\n    return false;\n}','static boolean allowed(double distanceSquared, int mode, boolean ownsMachine) {\n    return ownsMachine && distanceSquared >= 0 && distanceSquared <= 64 && mode >= 0 && mode < 3;\n}',[[[64,2,true],true,'Boundary allowed'],[[65,1,true],false,'Too far'],[[1,3,true],false,'Invalid mode'],[[1,0,false],false,'Not owner'],[[-1,0,true],false,'Invalid distance']],['Every condition must hold together.','Distance is already squared, so compare with 64, not 8.']);
E('interpolation','lerp','Return linear interpolation between previous and current using alpha. Tests keep alpha between 0 and 1.','static double lerp(double previous, double current, double alpha) {\n    return previous;\n}','static double lerp(double previous, double current, double alpha) {\n    return previous + (current - previous) * alpha;\n}',[[[10,20,0.25],12.5,'Quarter step'],[[10,20,0],10,'Start'],[[10,20,1],20,'End'],[[20,10,0.5],15,'Decreasing value']],['Scale the difference, not just current.','Add the scaled difference to previous.']);
E('rotation','drivenSpeed','Multiply sourceSpeed by ratio and negate the result when reverse is true.','static double drivenSpeed(double sourceSpeed, double ratio, boolean reverse) {\n    return 0.0;\n}','static double drivenSpeed(double sourceSpeed, double ratio, boolean reverse) {\n    double speed = sourceSpeed * ratio;\n    return reverse ? -speed : speed;\n}',[[[32,0.5,true],-16,'Reversing reduction'],[[32,2,false],64,'Speed increase'],[[-16,2,true],32,'Double reversal'],[[0,4,true],0,'Stopped source']],['Compute magnitude and sign in separate steps if clearer.','A ternary expression is condition ? whenTrue : whenFalse.']);
E('stress','canRun','A network runs when capacity is positive and demand is between zero and capacity inclusive.','static boolean canRun(int capacity, int demand) {\n    return false;\n}','static boolean canRun(int capacity, int demand) {\n    return capacity > 0 && demand >= 0 && demand <= capacity;\n}',[[[128,128],true,'Exact budget'],[[128,129],false,'Overloaded'],[[0,0],false,'No source'],[[128,0],true,'Idle powered network'],[[128,-1],false,'Invalid load']],['Use <= for the exact-capacity boundary.','A zero-capacity system has no source in this model.']);

